module div_8bit(
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output reg [15:0] result
);
    // Input registers to store the input operands
    reg [7:0] dividend_reg;
    reg [7:0] divisor_reg;

    // Output registers to store the result
    reg [7:0] remainder_reg;
    reg [7:0] quotient_reg;

    // Control signals
    reg [3:0] cnt;
    reg start_cnt;
    reg [8:0] NEG_DIVISOR;
    reg [8:0] SR;
    reg CO;
    reg [8:0] mux_result;
    reg [7:0] quotient_shift;
    reg [8:0] sub_result;
    reg [9:0] all_sub_result;
    reg [7:0] dividend_abs;
    reg [7:0] final_remainer;
    reg [7:0] final_quotient;
    reg is_final_quotient_sign;
    reg res_ready_reg;

    // Divisor extend logic
    always @(*) begin
        if (sign && divisor_reg[7]) begin
            divisor_extend = {1'b1, divisor_reg};
        end else begin
            divisor_extend = {1'b0, divisor_reg};
        end
    end

    // Division process
    always @(posedge clk) begin
        if (rst) begin
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            res_valid <= 0;
            res_ready_reg <= 0;
        end else if (opn_valid && !res_valid && !start_cnt) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            start_cnt <= 1;
            cnt <= 1;
            NEG_DIVISOR <= divisor_extend;
            SR <= {1'b0, dividend_abs, 1'b0};
        end else if (start_cnt) begin
            if (cnt == 4'b1000) begin
                cnt <= 0;
                start_cnt <= 0;
                remainder_reg <= SR[15:8];
                quotient_reg <= SR[7:0];
                res_valid <= 1;
            end else begin
                cnt <= cnt + 1;
                if (sign && (dividend_reg[7] ^ divisor_reg[7])) begin
                    {CO, sub_result} <= SR[8:0] + NEG_DIVISOR;
                end else begin
                    {CO, sub_result} <= SR[8:0] - NEG_DIVISOR;
                end
                mux_result <= CO ? sub_result : SR[8:0];
                quotient_shift <= SR[7:1];
                SR <= {mux_result, quotient_shift, CO, 1'b0};
            end
        end else if (res_valid && res_ready_reg) begin
            res_valid <= 0;
            res_ready_reg <= 0;
        end else begin
            res_ready_reg <= res_ready;
        end
    end

    // Result computation
    always @(*) begin
        if (sign && dividend_reg[7]) begin
            final_remainer = -remainder_reg;
        end else begin
            final_remainer = remainder_reg;
        end

        if (sign && (dividend_reg[7] ^ divisor_reg[7])) begin
            final_quotient = -quotient_reg;
        end else begin
            final_quotient = quotient_reg;
        end

        is_final_quotient_sign = sign && (dividend_reg[7] ^ divisor_reg[7]);
    end

    always @(*) begin
        result = {final_remainer, final_quotient};
    end
endmodule
